/**
 * 50 SQL analytics queries (standard core, dialect notes in comments; each file is one focused query over a commented schema).
 *
 * GENERATED by the example generators — do not edit by hand; re-run the
 * generator instead. Bodies are plain template literals using naming
 * tokens (⟦vr:…⟧ ⟦fn:…⟧ ⟦cl:…⟧ ⟦ky:…⟧) resolved by renderTokens at
 * creation time (Settings → Editor → Naming style), then reindent
 * converts the canonical 4-space indent to the configured style.
 */
import type {FileExample} from "@/lib/examples";
import {mkExample} from "./_helpers";
import {renderTokens} from "./_tokens";

const CAT = "Analytics";

const ex = (
    id: string, label: string, description: string, sub: string, baseName: string,
    body: string, fixedName?: string, ext: string = ".sql",
) => mkExample("sql", id, label, description, CAT, sub, baseName, ext, (s) => renderTokens(body, s), fixedName);

export const SQL_EXAMPLES: FileExample[] = [
    ex("sql-ex-001", "Filtering with WHERE", "Combining comparison, equality and boolean filters in one WHERE clause.", "Core queries", "select_where",
        `-- Sensor audit: pull the readings that need attention.
-- Schema:
--   measurements(id INTEGER PRIMARY KEY, sensor TEXT NOT NULL,
--                site TEXT NOT NULL, reading REAL NOT NULL,
--                taken_at TEXT NOT NULL)  -- ISO 'YYYY-MM-DD HH:MM'
-- Task: lab-site readings above 30 degrees, newest first.

SELECT id, sensor, reading, taken_at
FROM measurements
WHERE site = 'lab'
  AND reading > 30
ORDER BY taken_at DESC, id ASC
LIMIT 20;

-- Single quotes for string literals; double quotes are identifiers.
-- ORDER BY ... DESC, ... ASC: the id tie-break keeps runs stable.
-- AND binds tighter than OR: parenthesise when mixing them.
`),
    ex("sql-ex-002", "Paging with LIMIT and OFFSET", "ORDER BY with LIMIT and OFFSET for page three of a leaderboard.", "Core queries", "order_limit_offset",
        `-- Leaderboard paging with ORDER BY / LIMIT / OFFSET.
-- Schema:
--   students(id INTEGER PRIMARY KEY, name TEXT, track TEXT,
--            points INTEGER)
-- Task: page 3 of the top scorers, 5 rows per page.

SELECT name, track, points
FROM students
WHERE points IS NOT NULL
ORDER BY points DESC, name ASC
LIMIT 5
OFFSET 10;                -- skip pages 1 and 2 (2 * 5 rows)

-- OFFSET is 0-based: page N uses OFFSET (N - 1) * LIMIT.
-- Deep paging re-scans everything: keyset pagination fixes it with
--   WHERE (points, name) < (last_points, last_name)
-- (row-value comparisons: PostgreSQL; SQLite since 3.15).
`),
    ex("sql-ex-003", "Distinct counts", "COUNT variants that count rows, non-NULL values and distinct values.", "Core queries", "distinct_counts",
        `-- Counting distinct things — without the double counting joins cause later.
-- Schema:
--   trials(id INTEGER PRIMARY KEY, compound TEXT, analyst TEXT,
--          phase TEXT)
-- Task: how many distinct compounds and phases are in the book?

SELECT
  COUNT(DISTINCT compound)  AS compounds_total,
  COUNT(DISTINCT phase)     AS phases_seen,
  COUNT(DISTINCT analyst)   AS analysts_total,
  COUNT(*)                  AS total_rows
FROM trials;

-- COUNT(*)          rows in the table
-- COUNT(DISTINCT x) unique non-NULL values of x
-- COUNT(x)          non-NULL values of x (NULLs silently dropped)

-- The same distinct count per analyst:
SELECT analyst, COUNT(DISTINCT compound) AS compounds
FROM trials
GROUP BY analyst
ORDER BY compounds DESC;
`),
    ex("sql-ex-004", "NULL handling toolkit", "IS NULL, COALESCE and NULLIF turning missing values into reportable data.", "Core queries", "null_handling",
        `-- NULL handling: IS NULL, COALESCE, NULLIF.
-- Schema:
--   measurements(id INTEGER PRIMARY KEY, sensor TEXT,
--                reading REAL,           -- NULL when the logger dropped out
--                fallback_reading REAL)  -- value from the backup logger
-- Task: a report column that never shows NULL.

SELECT
  id,
  sensor,
  reading,
  COALESCE(reading, fallback_reading, -999)  AS reading_clean,
  CASE WHEN reading IS NULL THEN 'missing' ELSE 'ok' END AS status,
  NULLIF(sensor, 'UNKNOWN')                  AS sensor_known
FROM measurements
ORDER BY id;

-- COALESCE(a, b, c): the first non-NULL of a, b, c, left to right.
-- NULLIF(x, y): NULL when x = y, else x — turns sentinels into NULL.
-- WHERE x = NULL never matches: use IS NULL / IS NOT NULL.
`),
    ex("sql-ex-005", "Ranges and string patterns", "BETWEEN, IN and LIKE filters with the INSTR alternative noted.", "Core queries", "between_like",
        `-- Range and pattern filters: BETWEEN, IN, LIKE, INSTR.
-- Schema:
--   sales(id INTEGER PRIMARY KEY, product TEXT, region TEXT,
--          amount REAL, sale_date TEXT)   -- ISO 'YYYY-MM-DD'
-- Task: mid-year filament sales, largest first.

SELECT product, region, amount, sale_date
FROM sales
WHERE sale_date BETWEEN '2024-04-01' AND '2024-09-30'  -- both ends included
  AND region IN ('north', 'south')
  AND product LIKE '%filament%'    -- % matches any run of characters
ORDER BY amount DESC;

-- LIKE wildcards: % any string (even empty), _ exactly one character.
-- INSTR(product, 'filament') > 0 is the same search (SQLite, MySQL;
-- PostgreSQL spells it strpos). NOT BETWEEN / NOT IN / NOT LIKE negate.
-- Careful: NOT IN against a list containing NULL filters out EVERYTHING.
`),
    ex("sql-ex-006", "CASE buckets and pivot", "Value bands with searched CASE plus a hand-rolled pivot of counts per band.", "Core queries", "case_buckets",
        `-- CASE: value buckets in the SELECT list, plus a hand-rolled pivot.
-- Schema:
--   measurements(id INTEGER PRIMARY KEY, sensor TEXT, reading REAL)
-- Task: bucket readings and count them per sensor and band.

SELECT
  sensor,
  CASE
    WHEN reading < 20 THEN 'low'
    WHEN reading < 80 THEN 'normal'
    ELSE 'high'
  END AS band,
  COUNT(*) AS n
FROM measurements
GROUP BY sensor, band
ORDER BY sensor, band;

-- Pivot-lite: one row per sensor, one COLUMN per band.
SELECT
  sensor,
  SUM(CASE WHEN reading < 20 THEN 1 ELSE 0 END) AS n_low,
  SUM(CASE WHEN reading >= 20 AND reading < 80 THEN 1 ELSE 0 END) AS n_normal,
  SUM(CASE WHEN reading >= 80 THEN 1 ELSE 0 END) AS n_high
FROM measurements
GROUP BY sensor
ORDER BY sensor;

-- Searched CASE evaluates top-down and stops at the first match.
`),
    ex("sql-ex-007", "Aliases and computed columns", "Expression aliases in SELECT with table aliases and a division guard.", "Core queries", "computed_columns",
        `-- Computed columns and expression aliases.
-- Schema:
--   trials(id INTEGER PRIMARY KEY, compound TEXT, dose_mg REAL,
--          response REAL, hours_observed REAL)
-- Task: response rate per hour and per milligram, labelled clearly.

SELECT
  t.id,
  t.compound,
  t.dose_mg,
  t.response,
  t.response / t.hours_observed AS response_per_hour,
  t.response / t.dose_mg        AS response_per_mg,
  ROUND(t.response / t.dose_mg, 3) AS response_per_mg_r,
  t.dose_mg * t.hours_observed  AS dose_hours
FROM trials AS t
WHERE t.dose_mg > 0
  AND t.hours_observed > 0        -- guard both divisions
ORDER BY response_per_hour DESC;

-- AS names an expression for the output AND for ORDER BY.
-- Table aliases (trials AS t) keep qualified names short.
-- Integer division pitfall: SQLite 5 / 2 = 2; use CAST or * 1.0.
`),
    ex("sql-ex-008", "Date filtering by month", "ISO text dates with half-open ranges and substr month extraction.", "Core queries", "date_filtering",
        `-- Dates stored as ISO text plus dialect notes for extraction.
-- Schema:
--   sales(id INTEGER PRIMARY KEY, product TEXT, region TEXT,
--          amount REAL, sale_date TEXT)   -- ISO 'YYYY-MM-DD'
-- Task: monthly totals for 2024, oldest month first.

SELECT
  substr(sale_date, 1, 7) AS sale_month,   -- 'YYYY-MM' out of ISO text
  COUNT(*)                 AS n_sales,
  ROUND(SUM(amount), 2)    AS total
FROM sales
WHERE sale_date >= '2024-01-01'
  AND sale_date <  '2025-01-01'   -- half-open range: no time-of-day traps
GROUP BY substr(sale_date, 1, 7)
ORDER BY sale_month;

-- ISO-8601 text dates sort and compare correctly as plain strings.
-- PostgreSQL: a real date column with date_trunc('month', sale_date).
-- SQLite: strftime('%Y-%m', sale_date) equals the substr form here.
`),
    ex("sql-ex-009", "Text function toolkit", "Concatenation and upper, lower, substr, replace and trim on messy registrations.", "Core queries", "text_functions",
        `-- Text surgery: ||, upper, lower, substr, replace, trim, instr.
-- Schema:
--   students(id INTEGER PRIMARY KEY, name TEXT, email TEXT, track TEXT)
-- Task: build usernames and clean labels from raw registration rows.

SELECT
  upper(substr(name, 1, 3))                 AS initials3,
  lower(replace(name, ' ', '_'))            AS name_slug,
  substr(email, 1, instr(email, '@') - 1)   AS email_local,
  trim(track) || ' (' || upper(substr(track, 1, 2)) || ')' AS track_label
FROM students
WHERE email IS NOT NULL
ORDER BY name_slug;

-- || is the standard concatenation operator (SQLite, PostgreSQL).
-- trim() strips whitespace at both ends; length() counts characters.
-- instr(s, '@') is 0 when absent, so substr(..., 1, -1) yields ''
-- (INSTR: SQLite / MySQL; PostgreSQL uses strpos or position).
`),
    ex("sql-ex-010", "Rounding and numeric reports", "ROUND, ABS, ranges and a guarded percentage in one deviation report.", "Core queries", "numeric_formatting",
        `-- Numeric formatting: ROUND, ABS, min-max range, guarded percentage.
-- Schema:
--   measurements(id INTEGER PRIMARY KEY, sensor TEXT,
--                reading REAL, nominal REAL)  -- nominal = target value
-- Task: per-sensor deviation report, rounded for humans.

SELECT
  sensor,
  COUNT(*)                                     AS n,
  ROUND(AVG(reading), 2)                       AS mean_reading,
  ROUND(AVG(reading) - AVG(nominal), 3)        AS mean_deviation,
  ROUND(ABS(AVG(reading) - AVG(nominal)), 3)   AS abs_deviation,
  MAX(reading) - MIN(reading)                  AS range_reading,
  ROUND(100.0 * SUM(CASE WHEN reading > nominal THEN 1 ELSE 0 END)
        / COUNT(*), 1)                         AS pct_above_nominal
FROM measurements
GROUP BY sensor
ORDER BY abs_deviation DESC;

-- 100.0 * ... BEFORE the division keeps the result real, not integer.
-- ROUND(x, n) rounds halfway cases away from zero in SQLite.
`),
    ex("sql-ex-011", "Aggregates with GROUP BY", "The five basic aggregates grouped by region with the NULL-skipping rules noted.", "Aggregation", "group_aggregates",
        `-- The five basic aggregates with GROUP BY.
-- Schema:
--   sales(id INTEGER PRIMARY KEY, product TEXT, region TEXT,
--          amount REAL, sale_date TEXT)
-- Task: regional totals with order counts and size extremes.

SELECT
  region,
  COUNT(*)              AS n_sales,
  ROUND(SUM(amount), 2) AS total_amount,
  ROUND(AVG(amount), 2) AS avg_amount,
  MIN(amount)           AS smallest_sale,
  MAX(amount)           AS largest_sale
FROM sales
GROUP BY region
ORDER BY total_amount DESC;

-- Every selected column is either grouped (region) or aggregated.
-- SUM / AVG / MIN / MAX skip NULLs; COUNT(*) counts rows regardless.
-- An aggregate over ZERO rows gives one row: SUM is NULL, COUNT is 0.
`),
    ex("sql-ex-012", "Grouping by two columns", "GROUP BY on region and product makes one row per combination, not per key.", "Aggregation", "two_column_group",
        `-- GROUP BY on two columns: a region x product grid.
-- Schema:
--   sales(id INTEGER PRIMARY KEY, product TEXT, region TEXT,
--          amount REAL)
-- Task: totals for every region/product combination actually sold.

SELECT
  region,
  product,
  COUNT(*)              AS n_sales,
  ROUND(SUM(amount), 2) AS total_amount
FROM sales
GROUP BY region, product
ORDER BY region, total_amount DESC;

-- Two grouping keys -> one row per COMBINATION, not per key.
-- Combinations with zero sales simply do not appear; the cross-join
-- grid pattern manufactures those cells when you need them.
-- Grouping expressions may be selected by expression or alias.
`),
    ex("sql-ex-013", "HAVING filters groups", "The WHERE-before, HAVING-after split with a success-rate group filter.", "Aggregation", "having_filter",
        `-- HAVING filters GROUPS, WHERE filters ROWS.
-- Schema:
--   trials(id INTEGER PRIMARY KEY, compound TEXT, analyst TEXT,
--          outcome TEXT)   -- 'success' | 'failure' | 'inconclusive'
-- Task: compounds with at least 5 trials and over 60% success.

SELECT
  compound,
  COUNT(*) AS n_trials,
  ROUND(100.0 * SUM(CASE WHEN outcome = 'success' THEN 1 ELSE 0 END)
        / COUNT(*), 1) AS pct_success
FROM trials
GROUP BY compound
HAVING COUNT(*) >= 5
   AND 1.0 * SUM(CASE WHEN outcome = 'success' THEN 1 ELSE 0 END)
       / COUNT(*) > 0.60
ORDER BY pct_success DESC;

-- Logical evaluation order:
-- FROM -> WHERE -> GROUP BY -> HAVING -> SELECT -> ORDER BY.
-- WHERE cannot see aggregates; HAVING can (and may also re-test
-- plain columns, though WHERE is the cheaper place for those).
`),
    ex("sql-ex-014", "Top-N by aggregate", "Ordering grouped rows by an aggregate metric and keeping the head.", "Aggregation", "topn_aggregate",
        `-- Top-N by an aggregate: order the groups, keep the head.
-- Schema:
--   measurements(id INTEGER PRIMARY KEY, sensor TEXT, site TEXT,
--                reading REAL, taken_at TEXT)
-- Task: the three sensors with the widest reading span.

SELECT
  sensor,
  COUNT(*)                             AS n_readings,
  ROUND(MAX(reading) - MIN(reading), 2) AS span,
  ROUND(AVG(reading), 2)               AS mean_reading
FROM measurements
GROUP BY sensor
ORDER BY span DESC
LIMIT 3;

-- MAX - MIN per group is the cheapest spread proxy.
-- The same shape ranks any aggregate: AVG, SUM, a CASE-weighted rate.
-- For the top 3 PER SITE you need a window function or a subquery —
-- LIMIT applies to the whole result, not per group.
`),
    ex("sql-ex-015", "Weighted averages in SQL", "A credit-weighted average with CASE gates inside the aggregates.", "Aggregation", "case_weighted_avg",
        `-- Weighted metrics with CASE inside the aggregate.
-- Schema:
--   students(id INTEGER PRIMARY KEY, name TEXT, track TEXT,
--            score REAL, credits INTEGER)
-- Task: credit-weighted average score per track.

SELECT
  track,
  SUM(credits)                        AS total_credits,
  ROUND(SUM(score * credits) / SUM(credits), 2) AS weighted_avg,
  ROUND(AVG(score), 2)                AS unweighted_avg,
  SUM(CASE WHEN score >= 90 THEN credits ELSE 0 END) AS excellent_credits
FROM students
WHERE score IS NOT NULL
GROUP BY track
ORDER BY weighted_avg DESC;

-- Weighted mean = SUM(value * weight) / SUM(weight).
-- The CASE gate zeroes out non-qualifying rows inside the SUM.
-- AVG(score) silently drops NULL scores; the WHERE makes that explicit.
`),
    ex("sql-ex-016", "Share of total", "A scalar subquery computes the grand total behind each region share.", "Aggregation", "share_of_total",
        `-- Share of total: a scalar subquery vs the window alternative.
-- Schema:
--   sales(id INTEGER PRIMARY KEY, product TEXT, region TEXT,
--          amount REAL)
-- Task: each region's share of company-wide revenue.

SELECT
  region,
  ROUND(SUM(amount), 2) AS region_total,
  ROUND(100.0 * SUM(amount) /
        (SELECT SUM(amount) FROM sales), 1) AS pct_of_total
FROM sales
GROUP BY region
ORDER BY pct_of_total DESC;

-- The scalar subquery is uncorrelated here, so it is computed once —
-- cheap. The window alternative:
--   SELECT region, SUM(amount) AS region_total,
--          100.0 * SUM(amount) / SUM(SUM(amount)) OVER () AS pct
--   FROM sales GROUP BY region;
-- SUM(SUM(x)) OVER () works because windows evaluate AFTER grouping.
`),
    ex("sql-ex-017", "Ratio of sums", "The ratio-of-sums pattern weights every trial equally, unlike an average of ratios.", "Aggregation", "ratio_of_sums",
        `-- The ratio-of-sums pattern: SUM the parts, never AVG the ratios.
-- Schema:
--   trials(id INTEGER PRIMARY KEY, compound TEXT, batch TEXT,
--          tested INTEGER, passed INTEGER)   -- counts per batch
-- Task: the true pass rate per compound.

SELECT
  compound,
  SUM(tested)  AS tested_total,
  SUM(passed)  AS passed_total,
  ROUND(100.0 * SUM(passed) / SUM(tested), 2) AS pass_rate_pct
FROM trials
GROUP BY compound
ORDER BY pass_rate_pct DESC;

-- AVG(passed / tested) would weigh a 1-of-1 batch as much as a
-- 500-of-500 batch: SUM / SUM weights every trial equally.
-- Guard the denominator (WHERE tested > 0) when zero-tested batches
-- can appear — dividing by NULL yields NULL, by zero yields NULL too
-- in SQLite (an error in PostgreSQL).
`),
    ex("sql-ex-018", "Distinct per group", "COUNT(DISTINCT ...) inside GROUP BY counts unique values per group.", "Aggregation", "distinct_per_group",
        `-- Distinct values per group: how many analysts touched each compound?
-- Schema:
--   trials(id INTEGER PRIMARY KEY, compound TEXT, analyst TEXT,
--          phase TEXT, outcome TEXT)
-- Task: analyst breadth and phase coverage per compound.

SELECT
  compound,
  COUNT(DISTINCT analyst) AS n_analysts,
  COUNT(DISTINCT phase)   AS n_phases,
  COUNT(*)                AS n_trials,
  ROUND(1.0 * COUNT(DISTINCT analyst) / COUNT(DISTINCT phase), 2)
                          AS analysts_per_phase
FROM trials
GROUP BY compound
ORDER BY n_analysts DESC, compound;

-- COUNT(DISTINCT ...) is per GROUP, not global, inside GROUP BY.
-- SQLite allows several COUNT(DISTINCT ...) in one query; some
-- engines (older SQL Server) allow only one per query.
`),
    ex("sql-ex-019", "Subtotals with UNION ALL", "Region, product and grand-total rows stacked with UNION ALL where ROLLUP is unavailable.", "Aggregation", "rollup_union",
        `-- Rollup-lite: subtotal rows via UNION ALL.
-- Schema:
--   sales(id INTEGER PRIMARY KEY, product TEXT, region TEXT,
--          amount REAL)
-- Task: per-region totals, per-product totals, and the grand total.

SELECT region, 'ALL PRODUCTS' AS product, ROUND(SUM(amount), 2) AS total
FROM sales GROUP BY region
UNION ALL
SELECT 'ALL REGIONS', product, ROUND(SUM(amount), 2)
FROM sales GROUP BY product
UNION ALL
SELECT 'ALL REGIONS', 'ALL PRODUCTS', ROUND(SUM(amount), 2)
FROM sales
ORDER BY 1, 2;

-- Dialect notes:
-- * PostgreSQL / SQL Server: GROUP BY ROLLUP(region, product) builds
--   the hierarchy in one pass; GROUPING SETS ((region), (product), ())
--   is the general form. SQLite has no ROLLUP keyword.
-- * UNION ALL keeps it cheap: no deduplication pass.
-- * ORDER BY 1, 2 sorts by column position (portable everywhere).
`),
    ex("sql-ex-020", "Median by counting", "Ranking rows and keeping the middle rank or two computes a portable median.", "Aggregation", "median_counting",
        `-- Median by counting rows: rank the values, keep the middle rank(s).
-- Schema:
--   measurements(id INTEGER PRIMARY KEY, sensor TEXT, reading REAL)
-- Task: the median reading per sensor. PostgreSQL has
-- PERCENTILE_CONT(0.5) WITHIN GROUP; this ranking form is portable
-- to SQLite and anything with window functions.

SELECT
  sensor,
  COUNT(*)                  AS n_middle_rows,   -- 1 if n odd, 2 if even
  ROUND(AVG(reading), 3)    AS median_reading
FROM (
  SELECT
    sensor,
    reading,
    ROW_NUMBER() OVER (PARTITION BY sensor ORDER BY reading) AS rn,
    COUNT(*)     OVER (PARTITION BY sensor)                  AS n
  FROM measurements
) AS ranked
WHERE rn IN ((n + 1) / 2, (n + 2) / 2)   -- integer division finds the middle
GROUP BY sensor
ORDER BY sensor;

-- Averaging the one (odd n) or two (even n) middle rows IS the median.
`),
    ex("sql-ex-021", "Inner join with filter", "INNER JOIN matches rows on a key while WHERE trims the joined result.", "Joins", "inner_join_filter",
        `-- INNER JOIN with a filter on the dimension table.
-- Schema:
--   students(id INTEGER PRIMARY KEY, name TEXT, track TEXT)
--   measurements(student_id INTEGER, course TEXT, score REAL)
-- Task: physics-track students' course scores.

SELECT s.name, m.course, m.score
FROM students AS s
INNER JOIN measurements AS m
        ON m.student_id = s.id
WHERE s.track = 'physics'
ORDER BY s.name, m.course;

-- ON states HOW rows match; WHERE filters the JOINED result.
-- An inner join drops rows without a partner on either side.
-- Putting the track filter into ON instead of WHERE would change
-- nothing here — for inner joins the two are equivalent.
`),
    ex("sql-ex-022", "Left join finds missing", "LEFT JOIN plus IS NULL on the right key lists rows with no partner.", "Joins", "left_join_missing",
        `-- LEFT JOIN to FIND the rows that have no partner.
-- Schema:
--   students(id INTEGER PRIMARY KEY, name TEXT, track TEXT)
--   measurements(student_id INTEGER, course TEXT, score REAL)
-- Task: students with no recorded scores.

SELECT s.id, s.name, s.track
FROM students AS s
LEFT JOIN measurements AS m
       ON m.student_id = s.id
WHERE m.student_id IS NULL
ORDER BY s.name;

-- Pattern: LEFT JOIN + WHERE right-key IS NULL = the "no match" rows.
-- Test a column that is NULL when unmatched: the join key (never NULL
-- in the right table) is the safe choice — score could be NULL anyway.
-- The counting cousin: COUNT(m.course) is 0 for unmatched students.
`),
    ex("sql-ex-023", "Self join pairs", "One table joined to itself under two aliases builds distinct same-track pairs.", "Joins", "self_join_pairs",
        `-- Self join: a table joined to itself under two aliases.
-- Schema:
--   students(id INTEGER PRIMARY KEY, name TEXT, track TEXT)
-- Task: every distinct pair of students on the same track.

SELECT a.name AS student_a, b.name AS student_b, a.track
FROM students AS a
JOIN students AS b
  ON a.track = b.track
 AND a.id < b.id              -- each unordered pair exactly once
ORDER BY a.track, student_a, student_b;

-- a.id < b.id removes mirror pairs (a,b) vs (b,a) and self-pairs.
-- Same table, two aliases, two independent row streams.
-- The hierarchy flavour: JOIN staff AS mgr ON e.manager_id = mgr.id.
`),
    ex("sql-ex-024", "Anti-join with NOT EXISTS", "NOT EXISTS selects rows for which the correlated subquery stays empty.", "Joins", "anti_join",
        `-- Anti-join with NOT EXISTS: rows with NO matching sub-row.
-- Schema:
--   experiments(id INTEGER PRIMARY KEY, title TEXT, started_on TEXT)
--   measurements(experiment_id INTEGER, value REAL, taken_on TEXT)
-- Task: experiments that produced no measurements at all.

SELECT e.id, e.title, e.started_on
FROM experiments AS e
WHERE NOT EXISTS (
    SELECT 1
    FROM measurements AS m
    WHERE m.experiment_id = e.id
)
ORDER BY e.started_on;

-- NOT EXISTS is NULL-safe (unlike NOT IN with NULLs in the list) and
-- the standard, optimiser-friendly form. SELECT 1: the projection is
-- irrelevant, only emptiness matters.
`),
    ex("sql-ex-025", "Semi-join with EXISTS", "EXISTS keeps outer rows that have a match without duplicating them per match.", "Joins", "semi_join",
        `-- Semi-join with EXISTS: keep rows that HAVE a matching sub-row,
-- but do not duplicate them per match.
-- Schema:
--   experiments(id INTEGER PRIMARY KEY, title TEXT, lab TEXT)
--   measurements(experiment_id INTEGER, value REAL, taken_on TEXT)
-- Task: experiments with at least one out-of-range value.

SELECT e.id, e.title, e.lab
FROM experiments AS e
WHERE EXISTS (
    SELECT 1
    FROM measurements AS m
    WHERE m.experiment_id = e.id
      AND (m.value > 100 OR m.value < -100)
)
ORDER BY e.id;

-- EXISTS is a true/false test per outer row: each experiment appears
-- once, however many extreme measurements it has. An INNER JOIN would
-- repeat it once per matching row — the classic double-count bug.
`),
    ex("sql-ex-026", "Three-table star join", "A fact table joined to two dimensions on surrogate keys with a dimension filter.", "Joins", "star_join",
        `-- Three-table star join: the fact table in the middle, dimensions around.
-- Schema:
--   measurements(id INTEGER PRIMARY KEY, sensor_id INTEGER,
--                site_id INTEGER, reading REAL, taken_on TEXT)   -- fact
--   sensors(id INTEGER PRIMARY KEY, code TEXT, model TEXT)       -- dim
--   sites(id INTEGER PRIMARY KEY, name TEXT, zone TEXT)          -- dim
-- Task: a human-readable reading log for the north zone.

SELECT si.name AS site, s.code AS sensor, s.model,
       m.reading, m.taken_on
FROM measurements AS m
JOIN sensors AS s  ON s.id  = m.sensor_id
JOIN sites   AS si ON si.id = m.site_id
WHERE si.zone = 'north'
ORDER BY m.taken_on DESC, m.id
LIMIT 25;

-- Join the fact table to each dimension on its surrogate key.
-- Filter on the dimension column, not on a code copied into the fact.
-- Filtering in ON or in WHERE is equivalent for inner joins.
`),
    ex("sql-ex-027", "Join then aggregate", "Aggregating over a joined fact-and-dimension shape with distinct counting.", "Joins", "join_aggregate",
        `-- JOIN then GROUP BY: aggregate over the joined shape.
-- Schema:
--   sensors(id INTEGER PRIMARY KEY, code TEXT, model TEXT)
--   measurements(id INTEGER PRIMARY KEY, sensor_id INTEGER,
--                reading REAL, taken_on TEXT)
-- Task: reading counts and means per sensor MODEL.

SELECT
  s.model,
  COUNT(*)              AS n_readings,
  COUNT(DISTINCT s.id)  AS n_sensors,
  ROUND(AVG(m.reading), 2) AS mean_reading
FROM measurements AS m
JOIN sensors AS s ON s.id = m.sensor_id
GROUP BY s.model
ORDER BY n_readings DESC;

-- GROUP BY s.model collapses the sensor dimension inside each model.
-- COUNT(DISTINCT s.id) reports how many sensors fed each row.
-- Rows whose sensor_id matches no sensor vanish (inner join); a LEFT
-- JOIN would keep them with NULL model.
`),
    ex("sql-ex-028", "Cross join grid", "CROSS JOIN manufactures the full combination grid that a LEFT JOIN then fills.", "Joins", "cross_join_grid",
        `-- CROSS JOIN: every combination — build the full grid first, fill later.
-- Schema:
--   sensors(id INTEGER PRIMARY KEY, code TEXT)
--   sites(id INTEGER PRIMARY KEY, name TEXT)
--   readings(sensor_id INTEGER, site_id INTEGER, reading REAL)
-- Task: all sensor x site cells, INCLUDING the empty ones.

SELECT s.code, si.name,
       COUNT(r.reading)   AS n_readings,
       ROUND(AVG(r.reading), 2) AS mean_reading
FROM sensors AS s
CROSS JOIN sites AS si
LEFT JOIN readings AS r
       ON r.sensor_id = s.id AND r.site_id = si.id
GROUP BY s.code, si.name
ORDER BY s.code, si.name;

-- The cross join manufactures the cells; LEFT JOIN attaches what
-- exists; COUNT(r.reading) shows 0 for the empty ones.
-- CROSS JOIN of two BIG tables explodes to N x M rows: here that is
-- the point (a small grid), elsewhere it is a forgotten ON clause.
`),
    ex("sql-ex-029", "Join with COALESCE fallback", "Two LEFT JOINs with COALESCE supply a label and a note or defaults.", "Joins", "coalesce_join",
        `-- COALESCE across joins: fall back when the optional side is missing.
-- Schema:
--   measurements(id INTEGER PRIMARY KEY, sensor_id INTEGER,
--                reading REAL)
--   sensors(id INTEGER PRIMARY KEY, code TEXT)
--   sensor_notes(sensor_id INTEGER, note TEXT)   -- sparse, optional
-- Task: every reading with its sensor label and any note, or defaults.

SELECT
  m.id,
  COALESCE(s.code, 'SENSOR ' || m.sensor_id) AS sensor_label,
  m.reading,
  COALESCE(sn.note, 'no note')               AS note
FROM measurements AS m
LEFT JOIN sensors      AS s  ON s.id = m.sensor_id
LEFT JOIN sensor_notes AS sn ON sn.sensor_id = m.sensor_id
ORDER BY m.id
LIMIT 20;

-- LEFT JOIN + COALESCE is "value if present, fallback if not" in one
-- column. Never test a LEFT JOIN column with = NULL: use IS NULL.
-- The fallback here even rebuilds a label from the raw foreign key.
`),
    ex("sql-ex-030", "Multiple joins with aliases", "Four tables, four aliases and one question answered through them all.", "Joins", "multi_join_aliases",
        `-- Four tables, four aliases, one question.
-- Schema:
--   students(id INTEGER PRIMARY KEY, name TEXT, track TEXT)
--   trials(id INTEGER PRIMARY KEY, compound TEXT)
--   assignments(student_id INTEGER, trial_id INTEGER)
--   measurements(trial_id INTEGER, value REAL, valid INTEGER)
-- Task: valid measurements per student, via their assigned trials.

SELECT
  st.name,
  t.compound,
  COUNT(m.id)            AS n_measurements,
  ROUND(AVG(m.value), 2) AS mean_value
FROM assignments AS a
JOIN students         AS st ON st.id = a.student_id
JOIN trials           AS t  ON t.id  = a.trial_id
LEFT JOIN measurements AS m
       ON m.trial_id = a.trial_id AND m.valid = 1
GROUP BY st.name, t.compound
ORDER BY st.name, t.compound;

-- Short aliases keep the ON lines readable; qualify EVERY column once
-- two tables share a name (id appears in all of them).
-- The LEFT JOIN keeps assigned pairs that have no valid measurements.
`),
    ex("sql-ex-031", "ROW_NUMBER sequences", "A gap-free per-partition row counter driven by the window ORDER BY.", "Window functions", "row_number",
        `-- ROW_NUMBER(): a unique, gap-free sequence within each partition.
-- Schema:
--   measurements(id INTEGER PRIMARY KEY, sensor TEXT,
--                reading REAL, taken_at TEXT)
-- Task: number each sensor's readings oldest to newest.

SELECT
  id,
  sensor,
  taken_at,
  reading,
  ROW_NUMBER() OVER (PARTITION BY sensor
                     ORDER BY taken_at, id) AS reading_no
FROM measurements
ORDER BY sensor, reading_no
LIMIT 30;

-- PARTITION BY restarts the counter per sensor.
-- The ORDER BY inside OVER() sets the sequence and is INDEPENDENT of
-- the outer ORDER BY. Ties are broken deterministically by adding id.
`),
    ex("sql-ex-032", "RANK versus DENSE_RANK", "The three ranking functions side by side on a points leaderboard with ties.", "Window functions", "rank_dense_rank",
        `-- RANK, DENSE_RANK, ROW_NUMBER side by side.
-- Schema:
--   students(id INTEGER PRIMARY KEY, name TEXT, track TEXT,
--            points INTEGER)
-- Task: the leaderboard with all three ranking flavours.

SELECT
  name,
  points,
  ROW_NUMBER() OVER (ORDER BY points DESC) AS row_num,
  RANK()       OVER (ORDER BY points DESC) AS rnk,
  DENSE_RANK() OVER (ORDER BY points DESC) AS dense_rnk
FROM students
ORDER BY points DESC, name
LIMIT 15;

-- Tied points: ROW_NUMBER splits ties arbitrarily (1, 2, 3, ...),
-- RANK leaves gaps after ties (1, 1, 3), DENSE_RANK does not (1, 1, 2).
-- All three share one OVER clause shape: PARTITION BY is optional.
`),
    ex("sql-ex-033", "LAG deltas", "LAG() reaches the previous row inside a partition to build a change column.", "Window functions", "lag_lead",
        `-- LAG(): the previous row's value, for change columns.
-- Schema:
--   sales(id INTEGER PRIMARY KEY, product TEXT, region TEXT,
--          amount REAL, sale_date TEXT)
-- Task: day-over-day change per product.

SELECT
  sale_date,
  product,
  amount,
  LAG(amount) OVER (PARTITION BY product
                    ORDER BY sale_date) AS prev_amount,
  amount - LAG(amount) OVER (PARTITION BY product
                             ORDER BY sale_date) AS delta
FROM sales
ORDER BY product, sale_date;

-- The first row per product has NULL prev_amount and NULL delta:
-- COALESCE(delta, 0) or filtering in a subquery cleans that up.
-- LEAD() is the forward-looking twin.
`),
    ex("sql-ex-034", "Moving average window", "AVG OVER a ROWS BETWEEN frame gives a trailing moving average.", "Window functions", "moving_average",
        `-- Moving average: AVG OVER a sliding row frame.
-- Schema:
--   measurements(id INTEGER PRIMARY KEY, sensor TEXT,
--                reading REAL, taken_at TEXT)
-- Task: a 3-reading trailing moving average for one sensor.

SELECT
  taken_at,
  reading,
  ROUND(AVG(reading) OVER (
    PARTITION BY sensor
    ORDER BY taken_at, id
    ROWS BETWEEN 2 PRECEDING AND CURRENT ROW
  ), 2) AS moving_avg_3
FROM measurements
WHERE sensor = 'T-104'
ORDER BY taken_at;

-- ROWS BETWEEN 2 PRECEDING AND CURRENT ROW = the current row plus the
-- two before it, exactly. RANGE BETWEEN would lump together all rows
-- sharing an ORDER BY value — usually NOT what a time series wants.
`),
    ex("sql-ex-035", "Cumulative sum window", "SUM OVER an unbounded-start frame produces the running total per product.", "Window functions", "cumulative_sum",
        `-- Running total: SUM OVER with an explicit unbounded-start frame.
-- Schema:
--   sales(id INTEGER PRIMARY KEY, product TEXT, region TEXT,
--          amount REAL, sale_date TEXT)
-- Task: cumulative revenue per product by date.

SELECT
  sale_date,
  product,
  amount,
  ROUND(SUM(amount) OVER (
    PARTITION BY product
    ORDER BY sale_date
    ROWS UNBOUNDED PRECEDING
  ), 2) AS cumulative_amount
FROM sales
ORDER BY product, sale_date;

-- With ORDER BY and NO frame, the default is RANGE UNBOUNDED PRECEDING
-- TO CURRENT ROW: peer rows (same date) share one running value. An
-- explicit ROWS frame advances the total row by row — usually the
-- intent for running totals.
`),
    ex("sql-ex-036", "First and last values", "FIRST_VALUE with the default frame and LAST_VALUE with an opened frame explained.", "Window functions", "first_last_value",
        `-- FIRST_VALUE / LAST_VALUE and the frame trap.
-- Schema:
--   measurements(id INTEGER PRIMARY KEY, sensor TEXT,
--                reading REAL, taken_at TEXT)
-- Task: each reading beside the sensor's first reading and its
-- running maximum to date.

SELECT
  taken_at,
  reading,
  FIRST_VALUE(reading) OVER (
    PARTITION BY sensor ORDER BY taken_at, id
    ROWS UNBOUNDED PRECEDING
  ) AS first_reading,
  LAST_VALUE(reading) OVER (
    PARTITION BY sensor ORDER BY taken_at, id
    ROWS BETWEEN UNBOUNDED PRECEDING AND UNBOUNDED FOLLOWING
  ) AS last_reading
FROM measurements
WHERE sensor = 'H-221'
ORDER BY taken_at;

-- LAST_VALUE defaults to "... AND CURRENT ROW", so it returns the
-- CURRENT row unless the frame is opened to UNBOUNDED FOLLOWING.
-- That default surprises everyone exactly once.
`),
    ex("sql-ex-037", "NTILE buckets", "NTILE splits the ordered rows into a fixed number of near-equal buckets.", "Window functions", "ntile_buckets",
        `-- NTILE(n): fixed-count buckets, as equal as the row count allows.
-- Schema:
--   students(id INTEGER PRIMARY KEY, name TEXT, track TEXT,
--            points INTEGER)
-- Task: split the students into performance quintiles.

SELECT
  name,
  points,
  NTILE(5) OVER (ORDER BY points DESC) AS quintile
FROM students
ORDER BY quintile, points DESC;

-- NTILE(5) makes 5 buckets: spare rows land in the EARLIER buckets
-- (17 rows -> bucket sizes 4, 4, 3, 3, 3).
-- Contrast PERCENT_RANK() for a 0-to-1 position, or CASE WHEN
-- points >= 90 ... for business-defined bands with fixed cut-offs.
`),
    ex("sql-ex-038", "PERCENT_RANK positions", "PERCENT_RANK and CUME_DIST locate each value inside its own distribution.", "Window functions", "percent_rank",
        `-- PERCENT_RANK(): relative position from 0 to 1 within a partition.
-- Schema:
--   measurements(id INTEGER PRIMARY KEY, sensor TEXT, reading REAL)
-- Task: where each reading sits within its own sensor's distribution.

SELECT
  id,
  sensor,
  reading,
  ROUND(PERCENT_RANK() OVER (PARTITION BY sensor
                             ORDER BY reading), 3) AS pct_rank,
  ROUND(100.0 * CUME_DIST() OVER (PARTITION BY sensor
                                  ORDER BY reading), 1) AS pct_below
FROM measurements
ORDER BY sensor, reading
LIMIT 40;

-- PERCENT_RANK = (rank - 1) / (rows - 1): first row 0, last row 1.
-- CUME_DIST = fraction of rows with a value <= the current row.
-- Both answer "how deep into the pack is this value?".
`),
    ex("sql-ex-039", "Top one per group", "Ranking in a subquery then filtering outside picks one row per group.", "Window functions", "top1_per_group",
        `-- Top-1 per group: rank in a subquery, filter outside.
-- Schema:
--   measurements(id INTEGER PRIMARY KEY, sensor TEXT,
--                reading REAL, taken_at TEXT)
-- Task: the single most extreme reading per sensor.

SELECT sensor, taken_at, reading
FROM (
  SELECT
    sensor, taken_at, reading,
    ROW_NUMBER() OVER (
      PARTITION BY sensor
      ORDER BY ABS(reading - 50) DESC, id   -- farthest from the target 50
    ) AS rn
  FROM measurements
) AS ranked
WHERE rn = 1
ORDER BY sensor;

-- Windows cannot be filtered in WHERE (they evaluate after it), so
-- rank in a subquery or CTE and filter rn = 1 outside. For ALL ties at
-- the top, switch to RANK() ... WHERE rnk = 1.
`),
    ex("sql-ex-040", "Year-over-year with LAG", "Aggregate to yearly totals first, then LAG the aggregate to build growth percentages.", "Window functions", "year_over_year",
        `-- Year-over-year growth: aggregate first, LAG the aggregate.
-- Schema:
--   sales(id INTEGER PRIMARY KEY, product TEXT, region TEXT,
--          amount REAL, sale_date TEXT)
-- Task: revenue per product per year with the YoY growth percent.

WITH yearly AS (
  SELECT
    product,
    substr(sale_date, 1, 4) AS sale_year,
    SUM(amount)             AS revenue
  FROM sales
  GROUP BY product, substr(sale_date, 1, 4)
)
SELECT
  product,
  sale_year,
  ROUND(revenue, 2) AS revenue,
  ROUND(100.0 * (revenue - LAG(revenue) OVER w)
        / LAG(revenue) OVER w, 1) AS yoy_pct
FROM yearly
WINDOW w AS (PARTITION BY product ORDER BY sale_year)
ORDER BY product, sale_year;

-- Window functions evaluate AFTER GROUP BY, so they sit happily on
-- the aggregate result. WINDOW names a reused OVER clause.
-- The first year per product has NULL yoy_pct (no previous year).
`),
    ex("sql-ex-041", "Single CTE", "One WITH block names the per-sensor averages, then queries them.", "CTE & subqueries", "single_cte",
        `-- One CTE: name an intermediate result, then query it.
-- Schema:
--   measurements(id INTEGER PRIMARY KEY, sensor TEXT, reading REAL)
-- Task: sensors whose average reading beats the global average.

WITH sensor_averages AS (
  SELECT sensor, AVG(reading) AS avg_reading
  FROM measurements
  GROUP BY sensor
)
SELECT sensor, ROUND(avg_reading, 3) AS avg_reading
FROM sensor_averages
WHERE avg_reading > (SELECT AVG(reading) FROM measurements)
ORDER BY avg_reading DESC;

-- The CTE is visible only to the ONE query that follows it, and reads
-- top-to-bottom like a local view. SQLite and PostgreSQL can both
-- inline it, so there is no materialisation cost by default.
`),
    ex("sql-ex-042", "Chained CTEs", "Three WITH blocks in a row, each building on the ones above it.", "CTE & subqueries", "chained_ctes",
        `-- Chained CTEs: each WITH block can use the ones defined above it.
-- Schema:
--   sales(id INTEGER PRIMARY KEY, product TEXT, region TEXT,
--         amount REAL)
-- Task: products above the average revenue of the TOP HALF of products.

WITH product_revenue AS (
  SELECT product, SUM(amount) AS revenue
  FROM sales
  GROUP BY product
),
ranked_products AS (
  SELECT product, revenue,
         NTILE(2) OVER (ORDER BY revenue DESC) AS half
  FROM product_revenue
),
upper_half_avg AS (
  SELECT AVG(revenue) AS avg_upper_revenue
  FROM ranked_products
  WHERE half = 1
)
SELECT rp.product, ROUND(rp.revenue, 2) AS revenue
FROM ranked_products AS rp
CROSS JOIN upper_half_avg AS ua
WHERE rp.revenue > ua.avg_upper_revenue
ORDER BY rp.revenue DESC;

-- Each CTE sees the previous ones; the final CROSS JOIN carries the
-- single scalar row along. Read it as three named steps, top to bottom.
`),
    ex("sql-ex-043", "Recursive counter", "WITH RECURSIVE generates an integer series with the termination condition explained.", "CTE & subqueries", "recursive_counter",
        `-- Recursive CTE: counting from 1 to 10 — the "hello world" of
-- WITH RECURSIVE. Supported by SQLite and PostgreSQL alike.
-- Task: generate the integer series itself; no table is needed.

WITH RECURSIVE numbers(n) AS (
  SELECT 1                    -- anchor: the first row
  UNION ALL
  SELECT n + 1                -- recursive step: extends the previous rows
  FROM numbers
  WHERE n < 10                -- termination: stop the recursion
)
SELECT n, n * n AS square, printf('%02d', n) AS padded
FROM numbers;

-- The anchor seeds the recursion; UNION ALL appends each step's rows.
-- The WHERE inside the recursive part is the termination condition —
-- without it the CTE never ends (the engine will not stop you).
-- printf is SQLite; PostgreSQL: to_char(n, 'FM00'), or simply
-- generate_series(1, 10) instead of the whole CTE.
`),
    ex("sql-ex-044", "Recursive org chart", "A recursive walk down a manager hierarchy that tracks depth and the chain path.", "CTE & subqueries", "org_chart",
        `-- Recursive CTE: walk a reporting hierarchy top-down.
-- Schema:
--   staff(id INTEGER PRIMARY KEY, name TEXT, manager_id INTEGER)
--   manager_id is NULL at the top of the tree, else a staff.id.
-- Task: every employee with their management depth and chain.

WITH RECURSIVE org_chart(id, name, manager_id, depth, path) AS (
  SELECT id, name, manager_id, 0, name          -- roots: no manager
  FROM staff
  WHERE manager_id IS NULL
  UNION ALL
  SELECT s.id, s.name, s.manager_id, oc.depth + 1,
         oc.path || ' > ' || s.name             -- one level deeper
  FROM staff AS s
  JOIN org_chart AS oc ON s.manager_id = oc.id
)
SELECT name, depth, path
FROM org_chart
ORDER BY depth, path;

-- The anchor selects the roots; the recursive part joins each
-- already-found node to its direct reports. || builds the chain.
-- The single recursive reference per step is the standard rule.
`),
    ex("sql-ex-045", "Correlated EXISTS", "A subquery that references the outer row, short-circuiting at the first match.", "CTE & subqueries", "correlated_exists",
        `-- Correlated EXISTS: the subquery references the outer row.
-- Schema:
--   experiments(id INTEGER PRIMARY KEY, title TEXT, lab TEXT)
--   measurements(experiment_id INTEGER, value REAL, taken_on TEXT)
-- Task: labs with at least one experiment holding a value over 900.

SELECT DISTINCT e.lab
FROM experiments AS e
WHERE EXISTS (
    SELECT 1
    FROM measurements AS m
    WHERE m.experiment_id = e.id
      AND m.value > 900
)
ORDER BY e.lab;

-- The subquery is (logically) re-evaluated per outer row, and EXISTS
-- stops at the FIRST matching row — cheap when matches are common.
-- DISTINCT collapses the duplicate labs the join-free form leaves.
`),
    ex("sql-ex-046", "Scalar subqueries in SELECT", "Each output row carries its group average and the global average as columns.", "CTE & subqueries", "scalar_subquery",
        `-- Scalar subqueries in the SELECT list: one column, at most one row.
-- Schema:
--   students(id INTEGER PRIMARY KEY, name TEXT, track TEXT,
--            points INTEGER)
-- Task: each student with the track average and the overall average.

SELECT
  name,
  track,
  points,
  (SELECT AVG(points) FROM students AS s2
    WHERE s2.track = s.track)         AS track_avg,
  (SELECT AVG(points) FROM students)  AS overall_avg,
  points - (SELECT AVG(points) FROM students AS s3
            WHERE s3.track = s.track) AS vs_track_avg
FROM students AS s
ORDER BY track, points DESC;

-- A scalar subquery must return at most one row and one column.
-- It is re-evaluated per outer row: fine for small tables, but a
-- window (AVG() OVER (PARTITION BY track)) is the scalable form.
`),
    ex("sql-ex-047", "Derived table with aggregate", "A FROM-clause subquery aggregates first, then joins to the dimension.", "CTE & subqueries", "derived_table",
        `-- Derived table (a subquery in FROM): aggregate first, join after.
-- Schema:
--   sensors(id INTEGER PRIMARY KEY, code TEXT, model TEXT)
--   measurements(id INTEGER PRIMARY KEY, sensor_id INTEGER,
--                reading REAL)
-- Task: sensors whose AVERAGE reading is below the fleet average.

SELECT s.code, s.model, ROUND(per_sensor.avg_reading, 3) AS avg_reading
FROM (
  SELECT sensor_id, AVG(reading) AS avg_reading
  FROM measurements
  GROUP BY sensor_id
) AS per_sensor
JOIN sensors AS s ON s.id = per_sensor.sensor_id
WHERE per_sensor.avg_reading < (
  SELECT AVG(reading) FROM measurements
)
ORDER BY per_sensor.avg_reading;

-- Aggregate inside the FROM subquery, then join to the dimension —
-- aggregating AFTER an outer join would mix NULL rows into the mean.
-- Every FROM-subquery MUST carry an alias (per_sensor here).
`),
    ex("sql-ex-048", "Correlated aggregate filter", "A WHERE clause comparing each row against a correlated per-group average.", "CTE & subqueries", "correlated_aggregate",
        `-- Correlated aggregate in WHERE: each row vs its own group's statistic.
-- Schema:
--   measurements(id INTEGER PRIMARY KEY, sensor TEXT, reading REAL)
-- Task: readings more than 5 units above their own sensor's average.

SELECT m.sensor, m.id, m.reading,
       ROUND((SELECT AVG(reading) FROM measurements AS m2
              WHERE m2.sensor = m.sensor), 2) AS sensor_avg
FROM measurements AS m
WHERE m.reading >
      (SELECT AVG(reading) FROM measurements AS m3
       WHERE m3.sensor = m.sensor) + 5
ORDER BY m.sensor, m.reading DESC;

-- The inner AVG is recomputed per outer row (quadratic in the worst
-- case); a CTE + JOIN precomputes it once. Both forms are standard —
-- the correlated one is the easier first draft.
`),
    ex("sql-ex-049", "UNION versus UNION ALL", "The same two row sets stacked with and without deduplication.", "CTE & subqueries", "union_union_all",
        `-- UNION deduplicates; UNION ALL keeps every row.
-- Schema:
--   trials(id INTEGER PRIMARY KEY, compound TEXT, analyst TEXT,
--          outcome TEXT)
-- Task: the compound list from two teams, both ways (an A/B pair).

SELECT compound FROM trials WHERE analyst IN ('ada', 'grace')
UNION
SELECT compound FROM trials WHERE outcome = 'success'
ORDER BY compound;

SELECT compound FROM trials WHERE analyst IN ('ada', 'grace')
UNION ALL
SELECT compound FROM trials WHERE outcome = 'success'
ORDER BY compound;

-- UNION sorts and deduplicates the combined rows: a compound that is
-- both team-tested AND successful appears once.
-- UNION ALL keeps duplicates and skips the dedup pass (cheaper).
-- Column counts and types must line up on both sides of the operator.
`),
    ex("sql-ex-050", "CTE plus window report", "The ending combo: CTE for the aggregate, window for rank and share, outer WHERE for top-N.", "CTE & subqueries", "cte_window_report",
        `-- The combo that ends most report queries: CTE -> window -> filter.
-- Schema:
--   sales(id INTEGER PRIMARY KEY, product TEXT, region TEXT,
--         amount REAL, sale_date TEXT)
-- Task: the top 3 products per region by revenue, with region share.

WITH region_product AS (
  SELECT
    region,
    product,
    SUM(amount) AS revenue
  FROM sales
  GROUP BY region, product
),
scored AS (
  SELECT
    region,
    product,
    ROUND(revenue, 2) AS revenue,
    DENSE_RANK() OVER (PARTITION BY region
                       ORDER BY revenue DESC) AS rnk,
    ROUND(100.0 * revenue / SUM(revenue) OVER (PARTITION BY region), 1)
                       AS pct_of_region
  FROM region_product
)
SELECT region, product, revenue, pct_of_region
FROM scored
WHERE rnk <= 3
ORDER BY region, rnk;

-- One CTE for the aggregate, one for the window scoring, an outer
-- WHERE for the top-3 cut. Windows see the GROUP BY result, so the
-- whole chain reads top-to-bottom without a second pass over sales.
`),
];
